<?php session_start();require_once __DIR__.'/config.php';require_once __DIR__.'/includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:musicas.php');exit;}$t=trim($_POST['titulo']??'');$a=trim($_POST['artista']??'');$u=trim($_POST['mp3_url']??'');if($t===''||!filter_var($u,FILTER_VALIDATE_URL)){header('Location:musicas.php');exit;}db()->prepare('INSERT INTO btm_musicas(nick,titulo,artista,mp3_url) VALUES(?,?,?,?)')->execute([player_nick(),$t,$a,$u]);header('Location:musicas.php');exit;